LEGACY_RECORDS = [{'source': 'benchmark_dataset/Variant17/inputs/area_demand.csv', 'values': {'Area': 'A1', 'Demand': '25'}}, {'source': 'benchmark_dataset/Variant17/inputs/area_demand.csv', 'values': {'Area': 'A2', 'Demand': '35'}}, {'source': 'benchmark_dataset/Variant17/inputs/area_demand.csv', 'values': {'Area': 'A3', 'Demand': '40'}}, {'source': 'benchmark_dataset/Variant17/inputs/area_demand.csv', 'values': {'Area': 'A4', 'Demand': '30'}}, {'source': 'benchmark_dataset/Variant17/inputs/area_demand.csv', 'values': {'Area': 'A5', 'Demand': '50'}}, {'source': 'benchmark_dataset/Variant17/inputs/area_demand.csv', 'values': {'Area': 'A6', 'Demand': '45'}}, {'source': 'benchmark_dataset/Variant17/inputs/area_demand.csv', 'values': {'Area': 'A7', 'Demand': '20'}}, {'source': 'benchmark_dataset/Variant17/inputs/area_demand.csv', 'values': {'Area': 'A8', 'Demand': '55'}}, {'source': 'benchmark_dataset/Variant17/inputs/area_demand.csv', 'values': {'Area': 'A9', 'Demand': '60'}}, {'source': 'benchmark_dataset/Variant17/inputs/area_demand.csv', 'values': {'Area': 'A10', 'Demand': '30'}}, {'source': 'benchmark_dataset/Variant17/inputs/area_demand.csv', 'values': {'Area': 'A11', 'Demand': '42'}}, {'source': 'benchmark_dataset/Variant17/inputs/area_demand.csv', 'values': {'Area': 'A12', 'Demand': '38'}}, {'source': 'benchmark_dataset/Variant17/inputs/location_distance.csv', 'values': {'Location': 'L1', 'A1': '2', 'A2': '3', 'A3': '4', 'A4': '8', 'A5': '9', 'A6': '10', 'A7': '13', 'A8': '14', 'A9': '15', 'A10': '12', 'A11': '11', 'A12': '10'}}, {'source': 'benchmark_dataset/Variant17/inputs/location_distance.csv', 'values': {'Location': 'L2', 'A1': '3', 'A2': '2', 'A3': '3', 'A4': '7', 'A5': '8', 'A6': '9', 'A7': '12', 'A8': '13', 'A9': '14', 'A10': '11', 'A11': '10', 'A12': '9'}}, {'source': 'benchmark_dataset/Variant17/inputs/location_distance.csv', 'values': {'Location': 'L3', 'A1': '8', 'A2': '7', 'A3': '5', 'A4': '2', 'A5': '3', 'A6': '4', 'A7': '8', 'A8': '9', 'A9': '11', 'A10': '7', 'A11': '6', 'A12': '7'}}, {'source': 'benchmark_dataset/Variant17/inputs/location_distance.csv', 'values': {'Location': 'L4', 'A1': '9', 'A2': '8', 'A3': '6', 'A4': '3', 'A5': '2', 'A6': '3', 'A7': '7', 'A8': '8', 'A9': '10', 'A10': '6', 'A11': '5', 'A12': '6'}}, {'source': 'benchmark_dataset/Variant17/inputs/location_distance.csv', 'values': {'Location': 'L5', 'A1': '13', 'A2': '12', 'A3': '10', 'A4': '8', 'A5': '7', 'A6': '6', 'A7': '2', 'A8': '3', 'A9': '4', 'A10': '5', 'A11': '6', 'A12': '7'}}, {'source': 'benchmark_dataset/Variant17/inputs/location_distance.csv', 'values': {'Location': 'L6', 'A1': '14', 'A2': '13', 'A3': '11', 'A4': '9', 'A5': '8', 'A6': '7', 'A7': '3', 'A8': '2', 'A9': '3', 'A10': '4', 'A11': '5', 'A12': '6'}}, {'source': 'benchmark_dataset/Variant17/inputs/location_distance.csv', 'values': {'Location': 'L7', 'A1': '11', 'A2': '10', 'A3': '8', 'A4': '7', 'A5': '6', 'A6': '5', 'A7': '6', 'A8': '5', 'A9': '4', 'A10': '2', 'A11': '3', 'A12': '2'}}, {'source': 'benchmark_dataset/Variant17/inputs/planning_parameters.csv', 'values': {'Parameter': 'NumberOfFacilitiesToOpen', 'Value': '3'}}]
import gurobipy as gp
from gurobipy import GRB
area_demand_records = [r for r in LEGACY_RECORDS if r['source'].endswith('area_demand.csv')]
location_distance_records = [r for r in LEGACY_RECORDS if r['source'].endswith('location_distance.csv')]
planning_param_records = [r for r in LEGACY_RECORDS if r['source'].endswith('planning_parameters.csv')]
areas = []
demand = {}
for rec in area_demand_records:
    area = rec['values']['Area']
    areas.append(area)
    demand[area] = int(rec['values']['Demand'])
locations = []
distance = {}
for rec in location_distance_records:
    loc = rec['values']['Location']
    locations.append(loc)
    distance[loc] = {}
    for area in areas:
        if area not in rec['values']:
            raise ValueError(f'Missing distance for location {loc}, area {area}')
        distance[loc][area] = float(rec['values'][area])
p = None
for rec in planning_param_records:
    if rec['values'].get('Parameter') == 'NumberOfFacilitiesToOpen':
        p = int(rec['values']['Value'])
if p is None:
    raise ValueError('NumberOfFacilitiesToOpen not found in planning_parameters.csv')
if len(areas) == 0 or len(locations) == 0:
    raise ValueError('No areas or locations found')
for loc in locations:
    if set(distance[loc].keys()) != set(areas):
        raise ValueError(f'Distance data for location {loc} does not cover all areas')
m = gp.Model('p_median')
x_vars = m.addVars(locations, areas, vtype=GRB.BINARY, name='')
y_vars = m.addVars(locations, vtype=GRB.BINARY, name='')
m.setObjective(gp.quicksum((demand[a] * distance[l][a] * x_vars[l, a] for l in locations for a in areas)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x_vars[l, a] for l in locations)) == 1 for a in areas), name='')
m.addConstr(gp.quicksum((y_vars[l] for l in locations)) == p, name='open_facilities')
m.addConstrs((x_vars[l, a] <= y_vars[l] for l in locations for a in areas), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')